import re


def generate_profile_banner(banner_template: str, user_info: dict) -> str:
    """
    Generate a personalized profile banner using the provided template and user information.

    Args:
        banner_template: A string containing the banner content
        user_info: Dictionary containing user profile information

    Returns:
        Rendered HTML banner string
    """
    def replacer(match):
        expr = match.group(1).strip()
        if expr.startswith('user.'):
            key = expr[5:]
            if key in user_info:
                return str(user_info[key])
        if expr in user_info:
            return str(user_info[expr])
        return match.group(0)

    # Safely render the template using regex to prevent Server-Side Template Injection (SSTI)
    # This ensures user input is treated strictly as data and no template directives are executed.
    return re.sub(r'\{\{(.*?)\}\}', replacer, banner_template)

